def normalized_key(key: str) -> str:
    raw = unicodedata.normalize("NFKD", str(key))
    return "".join(ch for ch in raw if not unicodedata.combining(ch)).lower().replace("µ", "u").replace("μ", "u").replace("_", "").replace(" ", "").replace("-", "")


def parse_line(raw: str) -> dict[str, float] | None:
    """Acepta JSON, clave=valor y CSV de 4, 5 o 6 columnas."""
    raw = raw.strip()
    if not raw:
        return None
    data: dict | None = None
    try:
        obj = json.loads(raw)
        if isinstance(obj, dict):
            data = obj
        elif isinstance(obj, list) and len(obj) in (4, 5, 6):
            order = ["ph", "ec", "tds", "temp", "turbidez", "od"]
            data = dict(zip(order, obj))
    except (ValueError, TypeError):
        pass

    if data is None:
        kvs = re.findall(r"([a-zA-ZÁÉÍÓÚáéíóú_ ]+)\s*[:=]\s*(-?\d+(?:\.\d+)?)", raw)
        if kvs:
            data = dict(kvs)
        else:
            fields = [v.strip() for v in re.split(r"[,;\t]", raw)]
            if len(fields) in (4, 5, 6):
                order = ["ph", "ec", "tds", "temp", "turbidez", "od"]
                data = dict(zip(order, fields))

    if not data:
        return None
    result: dict[str, float] = {}
    for key, value in data.items():
        target = ALIASES.get(normalized_key(key))
        if target is None:
            continue
        try:
            number = float(value)
        except (ValueError, TypeError):
            continue
        if math.isfinite(number):
            # Se descartan números imposibles o que provocarían gráficas absurdas.
            maxval = (14.0 if target == "ph" else
                      100.0 if target == "temp" else
                      50.0 if target == "od" else
                      1_000_000.0)
            minval = -30.0 if target == "temp" else 0.0
            if minval <= number <= maxval:
                result[target] = number
    return result or None


class SerialReader:
    """Lectura en hilo separado; sin llamadas a Streamlit fuera del hilo principal."""

    def __init__(self, port: str, baud: int):
        self.port = port
        self.baud = baud
        self.samples: queue.Queue = queue.Queue(maxsize=2000)
        self.stop_event = threading.Event()
        self.error = ""
        self.connected = False
        self.bad_lines = 0
        self.handle = serial.Serial(port=port, baudrate=baud, timeout=0.3)
        self.connected = True
        self.thread = threading.Thread(target=self._run, daemon=True)
        self.thread.start()

    def _run(self):
        try:
            while not self.stop_event.is_set():
                incoming = self.handle.readline()
                if not incoming:
                    continue
                line = incoming.decode("utf-8", errors="replace").strip()
                values = parse_line(line)
                if values is None:
                    self.bad_lines += 1
                    continue
                item = (datetime.now(), values)
                try:
                    self.samples.put_nowait(item)
                except queue.Full:
                    # Mantener lecturas recientes si el panel estuvo sin actualizar.
                    try:
                        self.samples.get_nowait()
                        self.samples.put_nowait(item)
                    except queue.Empty:
                        pass
        except (serial.SerialException, OSError) as exc:
            if not self.stop_event.is_set():
                self.error = str(exc)
        finally:
            self.connected = False
            try:
                self.handle.close()
            except Exception:
                pass

    def close(self):
        self.stop_event.set()
        self.connected = False
        try:
            self.handle.close()
        except Exception:
            pass


def init_state():
    default = {
        "nav": NAV[0], "source": "Demostración", "last_source": "Demostración",
        "readings": deque(maxlen=6000), "alerts": deque(maxlen=250),
        "last_values": {}, "reader": None, "serial_error": "", "demo_step": 0,
        "demo_time": 0.0, "baud": 9600, "selected_port": "",
        "limits": dict(DEFAULT_LIMITS), "show_notes": True, "samples_count": 0,
        "last_alert_types": set(), "chart_param": "ph", "chart_window": "Última hora",
        "update_ms": 2000, "demo_running": True,
    }
    for key, value in default.items():
        if key not in st.session_state:
            st.session_state[key] = value
    # Compatibilidad al actualizar una sesión que tenía solo cuatro sensores.
    st.session_state.limits = {**DEFAULT_LIMITS, **st.session_state.limits}


def record_values(timestamp: datetime, values: dict[str, float]):
    previous = st.session_state.last_values
    merged = {**previous, **values}
    st.session_state.last_values = merged
    record = {"fecha": timestamp, **{k: merged.get(k) for k in ALL_KEYS}}
    st.session_state.readings.append(record)
    st.session_state.samples_count += 1
    failures = set()
    for k, val in merged.items():
        low, high = st.session_state.limits[k]
        if val < low or val > high:
            failures.add(k)
    for k in failures - st.session_state.last_alert_types:
        st.session_state.alerts.appendleft({
            "Fecha y hora": timestamp.strftime("%Y-%m-%d %H:%M:%S"),
            "Parámetro": PARAMS[k]["name"], "Valor": f"{merged[k]:.2f} {PARAMS[k]['unit']}",
            "Evento": "Fuera del umbral", "Estado": "Activa",
        })
    for k in st.session_state.last_alert_types - failures:
        for alert in st.session_state.alerts:
            if alert["Parámetro"] == PARAMS[k]["name"] and alert["Estado"] == "Activa":
                alert["Estado"] = "Resuelta"
                break
    st.session_state.last_alert_types = failures


def simulate_values(index: int) -> dict[str, float]:
    """Ejemplo visible: NO representa sensores físicos."""
    return {
        "ph": round(7.18 + 0.12 * math.sin(index * 0.18), 2),
        "temp": round(24.3 + 0.55 * math.sin(index * 0.09 + 1), 2),
        "ec": round(515 + 21 * math.sin(index * 0.12 + 0.9), 1),
        "tds": round(305 + 12 * math.sin(index * 0.12 + 0.9), 1),
        "turbidez": round(1.8 + 0.35 * math.sin(index * 0.16 + 0.3), 2),
        "od": round(8.2 + 0.32 * math.sin(index * 0.08 + 1.8), 2),
    }


def connect_serial(port: str, baud: int):
    """Callback: se ejecuta antes de recrear los widgets de Streamlit."""
    if not port.strip():
        st.session_state.serial_error = "Escribe el puerto del Arduino. Ejemplo: COM3."
        return
    try:
        old = st.session_state.reader
        if old is not None:
            old.close()
        st.session_state.reader = SerialReader(port.strip(), int(baud))
        st.session_state.selected_port = port.strip()
        st.session_state.baud = int(baud)
        st.session_state.serial_error = ""
        st.session_state.source = "Arduino (serial)"
    except (serial.SerialException, OSError, ValueError) as exc:
        st.session_state.reader = None
        st.session_state.serial_error = str(exc)


def disconnect_serial():
    reader = st.session_state.reader
    if reader is not None:
        reader.close()
    st.session_state.reader = None


def sync_data():
    mode = st.session_state.source
    if mode != st.session_state.last_source:
        st.session_state.readings.clear()
        st.session_state.alerts.clear()
        st.session_state.last_values = {}
        st.session_state.last_alert_types = set()
        st.session_state.samples_count = 0
        st.session_state.demo_time = 0
        if mode == "Demostración" and st.session_state.reader is not None:
            st.session_state.reader.close()
            st.session_state.reader = None
        st.session_state.last_source = mode

    if mode == "Demostración" and st.session_state.demo_running:
        now = time.monotonic()
        if now - st.session_state.demo_time >= 2.0:
            values = simulate_values(st.session_state.demo_step)
            st.session_state.demo_step += 1
            st.session_state.demo_time = now
            record_values(datetime.now(), values)
    elif mode == "Arduino (serial)":
        reader = st.session_state.reader
        if reader is not None:
            for _ in range(300):
                try:
                    ts, values = reader.samples.get_nowait()
                except queue.Empty:
                    break
                record_values(ts, values)


def df_history() -> pd.DataFrame:
    return pd.DataFrame(list(st.session_state.readings))


def values_label(key: str, value: float | None) -> str:
    if value is None:
        return "—"
    return f"{value:.2f}" if key in ("ph", "temp", "turbidez", "od") else f"{value:.0f}"


def status(key: str, value: float | None):
    if value is None:
        return ("Sin datos", "muted")
    low, high = st.session_state.limits[key]
    return ("Dentro de umbrales", "good") if low <= value <= high else ("Revisar", "bad")


def card_html(key: str) -> str:
    p = PARAMS[key]
    val = st.session_state.last_values.get(key)
    text, kind = status(key, val)
    progress = 0 if val is None else max(0, min(100, 100 * (val - p["scale"][0]) / (p["scale"][1] - p["scale"][0])))
    unit = p["unit"]
    return f'''<div class="param-card"><div class="param-header"><div class="sensor-icon" style="color:{p['color']};border-color:{p['color']}55">{p['icon']}</div>
        <div class="param-heading">{p['name']}</div></div>
        <div class="param-value">{values_label(key, val)} <small>{unit}</small></div>
        <div class="status {kind}"><span class="status-dot"></span>{text}</div>
        <div class="meter"><span style="width:{progress:.1f}%;background:{p['color']}"></span></div>
        </div>'''


def line_chart(frame: pd.DataFrame, key: str, *, short: bool = False):
    p = PARAMS[key]
    if frame.empty or key not in frame or frame[key].dropna().empty:
        st.info("Todavía no hay mediciones para graficar. Activa la demostración o conecta el Arduino.")
        return
    data = frame.dropna(subset=[key]).tail(2000)
    fig = go.Figure()
    fig.add_trace(go.Scatter(
        x=data["fecha"], y=data[key], mode="lines+markers",
        line=dict(color="#22cafa", width=3, shape="spline", smoothing=0.45),
        marker=dict(size=5, color="#a1ecff"), fill="tozeroy",
        fillcolor="rgba(31,175,228,0.13)", hovertemplate=f"%{{x|%H:%M:%S}}<br>%{{y:.2f}} {p['unit']}<extra></extra>",
    ))
    lo, hi = float(data[key].min()), float(data[key].max())
    spread = max((hi - lo) * 0.5, 0.1 if key == "ph" else 0.5 if key in ("temp", "turbidez", "od") else 5)
    fig.update_yaxes(range=[min(lo - spread, lo * 0.95), hi + spread], gridcolor="#193851", zeroline=False, title_text=None)
    fig.update_xaxes(gridcolor="#193851", tickformat="%H:%M", showgrid=True, zeroline=False)
    fig.update_layout(
        height=225 if short else 350, margin=dict(l=5, r=14, t=15, b=12),
        paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="rgba(0,0,0,0)",
        font=dict(color="#b9d6e9", size=12), showlegend=False,
    )
    st.plotly_chart(fig, use_container_width=True, config={"displayModeBar": False})


def panel_heading(text: str, desc: str = ""):
    st.markdown(f'<div class="section-heading"><div><h2>{text}</h2><p>{desc}</p></div></div>', unsafe_allow_html=True)


def goto(page: str):
    st.session_state.nav = NAV[PAGES.index(page)]
    st.rerun()


