with st.sidebar:
    st.caption("GUÍA Y PANTALLAS DEL SISTEMA")
    st.radio("Navegación", NAV, key="nav", label_visibility="collapsed")
    st.divider()
    st.selectbox("Fuente de datos", ["Demostración", "Arduino (serial)"], key="source")
    reader = st.session_state.reader
    connection_label = "Conectado" if reader and reader.connected else "Sin conexión"
    st.markdown(f'<div class="sidebar-note"><strong>● {"Modo DEMO" if st.session_state.source == "Demostración" else connection_label}</strong><br>Lectura de pH · temperatura · EC · TDS · turbidez · O₂<br><br>USB serial: conectar desde <b>Ajustes</b>.</div>', unsafe_allow_html=True)

page = PAGES[NAV.index(st.session_state.nav)]
# Refresca únicamente las pantallas de monitoreo. En Ajustes, evita que los formularios se reinicien.
if page in ("Inicio", "Tendencias", "Alarmas"):
    st_autorefresh(interval=st.session_state.update_ms, key="aurambient_refresh")
sync_data()

def render_hero():
    source = "DEMO" if st.session_state.source == "Demostración" else "SERIAL"
    reader = st.session_state.reader
    connected = (reader is not None and reader.connected) if source == "SERIAL" else True
    live_text = "Simulación activa" if source == "DEMO" else ("Conectado al Arduino" if connected else "Esperando conexión")
    st.markdown(f'''<div class="hero">
       <div class="hero-brand">
         <img src="data:image/png;base64,{LOGO_BASE64}" alt="AURAmbient"/>
       </div>
       <div class="hero-right"><span class="chip">{source}</span>
        <span class="chip"><i class="on" style="background:{'#3ee98e' if connected else '#889cb1'}"></i>{live_text}</span>
        <span class="chip">◷ &nbsp; {datetime.now().strftime('%H:%M:%S')}</span></div></div>''', unsafe_allow_html=True)

render_hero()

if page == "Contenido":
    panel_heading("Contenido de la interfaz", "Recorrido por las ventanas del multiparámetro y sus funciones")
    st.markdown('<div class="guide-kicker">FUNCIONES PRINCIPALES</div>', unsafe_allow_html=True)
    GUIDE = [
        ("01", "Inicio · Panel principal", "Seis lecturas simultáneas y estado general.", "Inicio", None),
        ("02", "Tendencias · pH", "Evolución del pH y resumen estadístico.", "Tendencias", "ph"),
        ("03", "Tendencias · Temperatura", "Comportamiento térmico de la muestra en °C.", "Tendencias", "temp"),
        ("04", "Tendencias · Turbidez", "Variación de la turbidez medida en NTU.", "Tendencias", "turbidez"),
        ("05", "Tendencias · Conductividad", "Lecturas de conductividad eléctrica en µS/cm.", "Tendencias", "ec"),
        ("06", "Tendencias · TDS", "Sólidos totales disueltos expresados en ppm.", "Tendencias", "tds"),
        ("07", "Tendencias · Oxígeno disuelto", "Concentración de oxígeno en el agua en mg/L.", "Tendencias", "od"),
        ("08", "Calibración", "Guía de calibración y verificación de sensores.", "Calibración", None),
        ("09", "Alarmas", "Avisos de parámetros fuera de los umbrales configurados.", "Alarmas", None),
        ("10", "Ajustes", "Conexión, visualización, sensores y umbrales.", "Ajustes", None),
    ]
    for base in range(0, len(GUIDE), 2):
        cols = st.columns(2, gap="medium")
        for idx, col in enumerate(cols):
            num, name, desc, destination, sensor = GUIDE[base + idx]
            with col:
                with st.container(border=True):
                    st.markdown(f'<div class="guide-item"><div class="guide-number">{num}</div>'
                                f'<div><div class="guide-text-title">{name}</div>'
                                f'<div class="guide-text-desc">{desc}</div></div></div>',
                                unsafe_allow_html=True)
                    if st.button("Abrir pantalla →", key=f"guide_{num}", use_container_width=True):
                        if sensor is not None:
                            st.session_state.chart_param = sensor
                        goto(destination)
    st.markdown('<div class="guide-kicker" style="margin-top:26px">FUNCIONES COMPLEMENTARIAS</div>', unsafe_allow_html=True)
    st.markdown('<div class="guide-note">'
                '<strong>Seis parámetros:</strong> pH, temperatura, conductividad, TDS, turbidez y oxígeno disuelto. '
                '<br><strong>Modo DEMO:</strong> los seis valores son simulados. '
                '<br><strong>Modo SERIAL:</strong> turbidez y oxígeno disuelto requieren sensores y envío de sus datos desde Arduino.'
                '</div>', unsafe_allow_html=True)

elif page == "Inicio":
    panel_heading("Calidad del agua", "Visualización de seis parámetros en tiempo real · Arduino o demostración")
    left, right = st.columns([2.15, 1], gap="large")
    with left:
        st.markdown('<div class="param-grid">' + "".join(card_html(k) for k in KEYS) + '</div>', unsafe_allow_html=True)
        with st.container(border=True):
            header_a, header_b = st.columns([3, 1])
            with header_a:
                st.markdown('<div class="panel-title">⌁ &nbsp; Tendencia de pH</div>', unsafe_allow_html=True)
            with header_b:
                if st.button("Ver tendencias →", use_container_width=True):
                    goto("Tendencias")
            line_chart(df_history(), "ph", short=True)
    with right:
        v = st.session_state.last_values
        alarms = [k for k in v if status(k, v[k])[1] == "bad"]
        if not v:
            headline, txt, icon, style = "Sin mediciones", "Conecta el Arduino o activa el modo DEMO.", "○", ""
        elif alarms:
            headline, txt, icon, style = "Revisar lecturas", f"{len(alarms)} parámetro(s) fuera de los umbrales definidos.", "!", "warn-text"
        else:
            headline, txt, icon, style = "Lecturas normales", "Los valores recibidos cumplen los umbrales configurados.", "✓", "good-text"
        st.markdown(f'''<div class="info-card"><div class="info-tag">◈ &nbsp; ESTADO GENERAL</div>
          <div class="info-value {style}" style="font-size:1.4rem">{icon} &nbsp;{headline}</div>
          <div class="info-sub">{txt}</div></div>''', unsafe_allow_html=True)
        st.markdown(f'''<div class="info-card"><div class="info-tag">♢ &nbsp; ALERTAS</div>
          <div class="info-value">{len(alarms)} activas</div><div class="info-sub">Supervisión de los seis parámetros de calidad del agua.</div></div>''', unsafe_allow_html=True)
        if st.button("Revisar alarmas →", use_container_width=True):
            goto("Alarmas")
        time_text = st.session_state.readings[-1]["fecha"].strftime("%H:%M:%S") if st.session_state.readings else "—"
        st.markdown(f'''<div class="info-card"><div class="info-tag">ÚLTIMA LECTURA</div>
           <div class="info-value">{time_text}</div><div class="info-sub">{st.session_state.samples_count} muestras en la sesión.</div></div>''', unsafe_allow_html=True)
        st.caption("Los umbrales son orientativos. Este sistema no certifica que el agua sea potable.")

elif page == "Tendencias":
    panel_heading("Tendencias", "Análisis histórico de los parámetros registrados")
    c1, c2 = st.columns([2, 1])
    with c1:
        st.selectbox("Parámetro de la gráfica", TREND_KEYS, format_func=lambda k: PARAMS[k]["name"], key="chart_param")
    with c2:
        st.selectbox("Periodo de análisis", ["Últimos 10 minutos", "Última hora", "24 horas", "Todo el historial"], key="chart_window")
    frame = df_history()
    if st.session_state.chart_param in ("turbidez", "od") and (frame.empty or st.session_state.chart_param not in frame or frame[st.session_state.chart_param].dropna().empty):
        field = "turbidez" if st.session_state.chart_param == "turbidez" else "oxigeno_disuelto"
        st.info(f"Todavía no hay lecturas para este sensor. En modo SERIAL, asegúrate de enviar el campo JSON '{field}' desde Arduino.")
    if not frame.empty and st.session_state.chart_window != "Todo el historial":
        delta = {"Últimos 10 minutos": timedelta(minutes=10), "Última hora": timedelta(hours=1), "24 horas": timedelta(hours=24)}[st.session_state.chart_window]
        frame = frame[frame["fecha"] >= datetime.now() - delta]
    with st.container(border=True):
        st.markdown(f'<div class="panel-title">⌁ &nbsp; Tendencia de {PARAMS[st.session_state.chart_param]["name"]}</div>', unsafe_allow_html=True)
        line_chart(frame, st.session_state.chart_param)
    values = frame[st.session_state.chart_param].dropna() if not frame.empty else pd.Series(dtype=float)
    stats = st.columns(4)
    for col, title, value in zip(stats, ["Actual", "Mínimo", "Máximo", "Promedio"],
                                 [values.iloc[-1] if not values.empty else None,
                                  values.min() if not values.empty else None,
                                  values.max() if not values.empty else None,
                                  values.mean() if not values.empty else None]):
        col.metric(title, "—" if value is None else f"{value:.2f} {PARAMS[st.session_state.chart_param]['unit']}")
    if not frame.empty:
        st.download_button("⬇ Exportar mediciones CSV", frame.to_csv(index=False).encode("utf-8-sig"),
                           "AURAmbient_mediciones.csv", mime="text/csv")

elif page == "Calibración":
    panel_heading("Calibración", "Guía de verificación de sensores · procedimiento asistido")
    st.warning("Esta pantalla es una guía. No modifica la calibración del Arduino hasta que programes un protocolo de comandos y su confirmación.")
    selected = st.selectbox("Sensor", KEYS, format_func=lambda k: PARAMS[k]["name"])
    guides = {
        "ph": ("Soluciones buffer certificadas", ["Enjuaga y seca suavemente el electrodo.", "Introduce el sensor en el buffer pH 7,00 y espera estabilidad.", "Continúa con pH 4,00 y, si tu procedimiento lo requiere, pH 10,00.", "Guarda los coeficientes con el firmware del Arduino y verifica con una solución independiente."]),
        "ec": ("Patrón de conductividad", ["Limpia la celda y comprueba la temperatura del patrón.", "Sumerge la celda en un patrón apropiado (por ejemplo, 1413 µS/cm, si es compatible).", "Espera la estabilización y aplica la calibración en el controlador.", "Comprueba la lectura con un segundo patrón."]),
        "tds": ("Verificación de sólidos disueltos", ["Verifica primero la conductividad de la sonda.", "Configura el factor EC→TDS apropiado para el equipo y la muestra.", "Compara con una solución patrón indicada por el fabricante.", "Guarda y registra los resultados de la verificación."]),
        "temp": ("Referencia de temperatura", ["Coloca la sonda y un termómetro de referencia en el mismo medio.", "Espera hasta alcanzar equilibrio térmico.", "Compara ambas lecturas.", "Corrige el offset en el programa del Arduino, si fuera necesario."]),
        "turbidez": ("Patrones de turbidez (NTU)", ["Limpia la cubeta o ventana óptica según el fabricante.", "Realiza una referencia cero con el patrón o blanco indicado.", "Verifica el sensor con uno o varios estándares NTU compatibles.", "Registra los resultados y aplica los ajustes en el firmware si el sensor lo permite."]),
        "od": ("Oxígeno disuelto (mg/L)", ["Comprueba el tipo de sonda (óptica o electroquímica) y sus condiciones de uso.", "Verifica temperatura y compensación de presión/salinidad, si corresponde.", "Aplica la calibración de aire saturado y/o cero según el manual del sensor.", "Comprueba la lectura y guarda el resultado en el firmware."]),
    }
    title, steps = guides[selected]
    st.markdown(f'<div class="info-card"><div class="info-value">{title}</div><div class="info-sub">Procedimiento orientativo; utiliza el manual específico de tus sensores.</div></div>', unsafe_allow_html=True)
    for idx, step in enumerate(steps, 1):
        st.checkbox(f"Paso {idx} · {step}", key=f"check_{selected}_{idx}")
    st.info("Para automatizar esta sección, el Arduino debe implementar recepción de órdenes, calibración en firmware y respuesta de éxito/error.")

elif page == "Alarmas":
    panel_heading("Alarmas", "Umbrales definidos por el usuario y eventos registrados")
    current = st.session_state.last_values
    out = [k for k in current if status(k, current[k])[1] == "bad"]
    m1, m2, m3 = st.columns(3)
    m1.metric("Parámetros en alerta", len(out))
    m2.metric("Eventos registrados", len(st.session_state.alerts))
    m3.metric("Lecturas recibidas", st.session_state.samples_count)
    if out:
        for k in out:
            a, b = st.session_state.limits[k]
            st.error(f"{PARAMS[k]['name']}: {values_label(k, current[k])} {PARAMS[k]['unit']} · Umbral configurado: {a:g} a {b:g}")
    elif current:
        st.success("Sin alertas activas según los umbrales configurados.")
    else:
        st.info("Sin datos de sensores. Esperando mediciones.")
    st.markdown("#### Historial de eventos")
    if st.session_state.alerts:
        st.dataframe(pd.DataFrame(list(st.session_state.alerts)), use_container_width=True, hide_index=True)
    else:
        st.caption("Aún no se registran eventos.")
    st.caption("Los límites son de demostración y dependen del uso del agua; no son un dictamen de potabilidad.")

elif page == "Ajustes":
    panel_heading("Ajustes", "Conexión del Arduino, actualización y umbrales")
    tab1, tab2, tab3 = st.tabs(["🔌 Puerto serial", "⚙️ Visualización", "⚠️ Umbrales"])
    with tab1:
        st.markdown("#### Conectar Arduino por USB")
        st.info("La aplicación debe ejecutarse localmente en la computadora que tiene conectado el Arduino. GitHub/Streamlit Cloud no puede abrir directamente tu puerto COM o /dev/ttyUSB.")
        ports = list(list_ports.comports())
        port_names = [p.device for p in ports]
        st.caption("Puertos detectados: " + (", ".join(port_names) if port_names else "ninguno (puedes escribir la ruta manualmente)."))
        new_port = st.text_input("Puerto COM / USB", value=st.session_state.selected_port or (port_names[0] if port_names else ""), placeholder="COM3 o /dev/ttyUSB0")
        new_baud = st.selectbox("Baudios", [9600, 19200, 38400, 57600, 115200], index=[9600,19200,38400,57600,115200].index(st.session_state.baud))
        reader = st.session_state.reader
        a, b = st.columns(2)
        a.button("Conectar Arduino", use_container_width=True,
                 disabled=bool(reader and reader.connected),
                 on_click=connect_serial, args=(new_port, new_baud))
        b.button("Desconectar", use_container_width=True,
                 disabled=not bool(reader), on_click=disconnect_serial)
        reader = st.session_state.reader
        if reader is not None:
            st.write("Estado:", "🟢 Conectado" if reader.connected else "🔴 Desconectado", "· Líneas inválidas:", reader.bad_lines)
            if reader.error:
                st.error("Error del puerto: " + reader.error)
        if st.session_state.serial_error:
            st.error(st.session_state.serial_error)
        st.code('Serial.println(R"({"ph":7.18,"ec":515,"tds":305,"temp":24.3,"turbidez":1.8,"oxigeno_disuelto":8.2})");', language="cpp")
        st.caption("Envía una línea JSON por lectura con los 6 campos. También acepta CSV: 7.18,515,305,24.3,1.8,8.2, en el orden pH, EC, TDS, temperatura, turbidez, oxígeno disuelto. Las 4 columnas antiguas siguen siendo válidas, pero los sensores omitidos no mostrarán datos nuevos.")
    with tab2:
        st.selectbox("Frecuencia de actualización del panel", [1000, 2000, 3000, 5000], format_func=lambda x: f"{x/1000:g} segundos", key="update_ms")
        st.checkbox("Actualizar lecturas simuladas", key="demo_running")
        st.caption("La frecuencia del envío real se programa en el Arduino. Este ajuste controla cuánto se actualiza Streamlit.")
        if st.button("Vaciar historial de esta sesión"):
            st.session_state.readings.clear()
            st.session_state.alerts.clear()
            st.session_state.last_values = {}
            st.session_state.last_alert_types = set()
            st.session_state.samples_count = 0
            st.success("Historial de la sesión vaciado.")
    with tab3:
        st.caption("Los umbrales iniciales son únicamente ejemplos configurables, no normas de agua potable.")
        with st.form("thresholds"):
            updated_limits = {}
            for k in KEYS:
                st.markdown(f"**{PARAMS[k]['name']} ({PARAMS[k]['unit'] or 'sin unidad'})**")
                lcol, hcol = st.columns(2)
                lo, hi = st.session_state.limits[k]
                low = lcol.number_input("Mínimo", value=float(lo), key=f"limit_low_{k}")
                high = hcol.number_input("Máximo", value=float(hi), key=f"limit_high_{k}")
                updated_limits[k] = (low, high)
            if st.form_submit_button("Guardar umbrales"):
                if any(lo >= hi for lo, hi in updated_limits.values()):
                    st.error("El máximo debe ser mayor que el mínimo en todos los parámetros.")
                else:
                    st.session_state.limits = updated_limits
                    st.success("Umbrales actualizados.")

st.caption("AURAmbient · Seis parámetros del agua · DEMO: datos simulados · SERIAL: sensores físicos necesarios · No certifica potabilidad")



